<?php
namespace Tests\Feature\Api\Payouts;
use App\Models\PayoutRequest; use App\Services\Payouts\PayoutDestinationService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\Concerns\CreatesPayoutLedger; use Tests\Concerns\CreatesTradeXMobileSession; use Tests\TestCase;
class PayoutAccountingSecurityAndRateLimitTest extends TestCase { use CreatesPayoutLedger,CreatesTradeXMobileSession,RefreshDatabase;
 public function test_negative_adjustment_reduces_available_balance():void { $u=$this->createApiUser(['account_type'=>'PREMIUM']); $this->configurePayoutProfile($u); $c=$this->seedPayoutCommission($u,3000); $this->seedPayoutAdjustment($c,$u,-1000); $t=$this->issueBoundToken($u); $this->withToken($t)->getJson('/api/v1/payouts/summary')->assertOk()->assertJsonPath('data.adjustments.amount_cents',-1000)->assertJsonPath('data.available.amount_cents',2000); }
 public function test_failed_payout_releases_balance():void { $u=$this->createApiUser(['account_type'=>'PREMIUM']); $this->configurePayoutProfile($u); $this->seedPayoutCommission($u,3000); $t=$this->issueBoundToken($u); $this->withToken($t)->withHeader('Idempotency-Key','payout-fail-001')->postJson('/api/v1/payouts',['method'=>'PAYPAL','amount'=>'15.00'])->assertCreated(); PayoutRequest::query()->firstOrFail()->forceFill(['status'=>PayoutRequest::STATUS_FAILED,'failed_at'=>now(),'user_visible_reason'=>'Provider transfer failed.'])->save(); $this->withToken($t)->getJson('/api/v1/payouts/summary')->assertOk()->assertJsonPath('data.locked.amount_cents',0)->assertJsonPath('data.available.amount_cents',3000); }
 public function test_user_cannot_read_another_users_payout():void { $owner=$this->createApiUser(['account_type'=>'PREMIUM']); $other=$this->createApiUser(['account_type'=>'PREMIUM']); $snap=['method'=>PayoutRequest::METHOD_PAYPAL,'email'=>'owner@example.test']; $p=PayoutRequest::query()->create(['user_id'=>$owner->getKey(),'method'=>PayoutRequest::METHOD_PAYPAL,'status'=>PayoutRequest::STATUS_PENDING_REVIEW,'amount_cents'=>1500,'currency'=>'USD','destination_snapshot'=>$snap,'destination_fingerprint'=>app(PayoutDestinationService::class)->fingerprint($snap),'idempotency_key_hash'=>hash('sha256','idor-test-key'),'requested_at'=>now()]); $t=$this->issueBoundToken($other); $this->withToken($t)->getJson('/api/v1/payouts/'.$p->uuid)->assertNotFound()->assertJsonPath('error.code','PAYOUT_NOT_FOUND'); }
 public function test_kyc_gate_is_independent_and_configurable():void { config(['tradex_payouts.require_verified_kyc'=>true]); $u=$this->createApiUser(['account_type'=>'PREMIUM']); $this->configurePayoutProfile($u); $this->seedPayoutCommission($u,2000); $t=$this->issueBoundToken($u); $this->withToken($t)->getJson('/api/v1/payouts/summary')->assertOk()->assertJsonPath('data.kyc.required',true)->assertJsonPath('data.kyc.satisfied',false)->assertJsonPath('data.can_request_payout',false); $this->withToken($t)->withHeader('Idempotency-Key','payout-kyc-001')->postJson('/api/v1/payouts',['method'=>'PAYPAL','amount'=>'15.00'])->assertForbidden()->assertJsonPath('error.code','PAYOUT_KYC_REQUIRED'); }
 public function test_create_rate_limit_is_dedicated():void { config(['tradex_payouts.rate_limits.create_per_minute'=>1,'tradex_payouts.rate_limits.create_per_hour'=>10]); $u=$this->createApiUser(['account_type'=>'PREMIUM']); $this->configurePayoutProfile($u); $this->seedPayoutCommission($u,4000); $t=$this->issueBoundToken($u); $this->withToken($t)->withHeader('Idempotency-Key','payout-rate-001')->postJson('/api/v1/payouts',['method'=>'PAYPAL','amount'=>'15.00'])->assertCreated(); $this->withToken($t)->withHeader('Idempotency-Key','payout-rate-002')->postJson('/api/v1/payouts',['method'=>'PAYPAL','amount'=>'15.00'])->assertTooManyRequests(); }
}
